body.script:
let ALL_FILES = [];

async function openGameFullscreen(rawURL) {
    try {
        const response = await fetch(rawURL);
        const text = await response.text();

        const win = window.open("", "_blank");
        win.document.open();
        win.document.write(text);
        win.document.close();

    } catch (err) {
        alert("Failed to load file.");
        console.error(err);
    }
}

async function scanFolder(path = "") {
    const url = `https://api.github.com/repos/nguyenkhoinguyen08012012-stack/webs/contents/${path}`;
    const res = await fetch(url);
    const items = await res.json();

    let out = [];

    for (const item of items) {
        if (item.type === "file" && item.name.endsWith(".html")) {
            out.push(item.path);
        }
        if (item.type === "dir") {
            const sub = await scanFolder(item.path);
            out = out.concat(sub);
        }
    }

    return out;
}

function renderFiles(filter = null) {
    const container = document.getElementById("sections-container");
    container.innerHTML = "";

    let files = ALL_FILES;

    if (filter === "0-9") {
        files = files.filter(f => /^[0-9]/.test(f.cleanName));
    } else if (filter) {
        files = files.filter(f => f.cleanName.toLowerCase().startsWith(filter.toLowerCase()));
    }

    files.forEach(file => {
        const btn = document.createElement("input");
        btn.type = "button";
        btn.value = file.cleanName;

        btn.onclick = () => openGameFullscreen(file.rawURL);

        container.appendChild(btn);
    });
}

function createGroupButtons() {
    const groupDiv = document.getElementById("group-buttons");

    const allBtn = document.createElement("button");
    allBtn.className = "group-btn";
    allBtn.textContent = "All";
    allBtn.onclick = () => renderFiles(null);
    groupDiv.appendChild(allBtn);

    const numBtn = document.createElement("button");
    numBtn.className = "group-btn";
    numBtn.textContent = "0–9";
    numBtn.onclick = () => renderFiles("0-9");
    groupDiv.appendChild(numBtn);

    for (let i = 65; i <= 90; i++) {
        const letter = String.fromCharCode(i);
        const btn = document.createElement("button");
        btn.className = "group-btn";
        btn.textContent = letter;
        btn.onclick = () => renderFiles(letter);
        groupDiv.appendChild(btn);
    }
}

async function loadFiles() {
    const container = document.getElementById("sections-container");
    container.innerHTML = "
Loading...";

    let files = await scanFolder("");

    files.sort((a, b) => a.localeCompare(b));

    ALL_FILES = files.map(path => {
        const cleanName = path
            .replace(".html", "")
            .replace(/\//g, " / ");

        return {
            path,
            cleanName,
            rawURL: `https://raw.githubusercontent.com/nguyenkhoinguyen08012012-stack/webs/main/${path}`
        };
    });

    createGroupButtons();
    renderFiles(null);
}

loadFiles();
